	@Transactional
	@Override
	public SuccessRes insertCity(CityMasterSaveReq req) {
		SimpleDateFormat sdformat = new SimpleDateFormat("dd/MM/YYYY");
		SuccessRes res = new SuccessRes();
		CityMaster saveData = new CityMaster();
		List<CityMaster> list = new ArrayList<CityMaster>();
		DozerBeanMapper dozerMapper = new DozerBeanMapper();

		try {
			Calendar cal = new GregorianCalendar();
			cal.setTime(req.getEffectiveDate());cal.set(Calendar.HOUR_OF_DAY, 23);cal.set(Calendar.MINUTE, 59);
			Date startDate = cal.getTime();
			Date today = new Date();
			cal.setTime(req.getEffectiveDate());  cal.add(Calendar.DAY_OF_MONTH, -1); cal.set(Calendar.HOUR_OF_DAY, today.getHours()); cal.set(Calendar.MINUTE, today.getMinutes());
			Date oldEndDate = cal.getTime();
			cal.setTime(req.getEffectiveDate());
			cal.set(Calendar.HOUR_OF_DAY, today.getHours());cal.set(Calendar.MINUTE, today.getMinutes());
			Date effDate = cal.getTime();
			Date endDate = sdformat.parse("12/12/2050");

			String cityId = "";

			if (StringUtils.isBlank(req.getCityId().toString())) {
				// Save
				// Long totalCount = repo.count();
				Long totalCount = getMasterTableCount();
				cityId = Long.valueOf(totalCount + 1).toString();
				res.setResponse("Saved Successfully ");
				res.setSuccessId(cityId);

			} else {
				// Update
				// Get Less than Equal Today Record
				// Criteria
				cityId = req.getCityId();
				CriteriaBuilder cb = em.getCriteriaBuilder();
				CriteriaQuery<CityMaster> query = cb.createQuery(CityMaster.class);

				// Find All
				Root<CityMaster> b = query.from(CityMaster.class);

				// Select
				query.select(b);

				// Effective Date Max Filter
				Subquery<Long> effectiveDate = query.subquery(Long.class);
				Root<CityMaster> ocpm1 = effectiveDate.from(CityMaster.class);
				effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
				Predicate a1 = cb.equal(ocpm1.get("cityId"), b.get("cityId"));
				Predicate a2 = cb.lessThanOrEqualTo(ocpm1.get("effectiveDateStart"), startDate);
				effectiveDate.where(a1, a2);

				// Order By
				// List<Order> orderList = new ArrayList<Order>();
				// orderList.add(cb.asc(b.get("branchName")));

				// Where
				Predicate n1 = cb.equal(b.get("status"), "Y");
				Predicate n2 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
				Predicate n3 = cb.equal(b.get("cityId"), req.getCityId());

				query.where(n1, n2, n3);// .orderBy(orderList);

				// Get Result
				TypedQuery<CityMaster> result = em.createQuery(query);
				list = result.getResultList();

				if (list.size() > 0) {
					repo.delete(list.get(0));
				}
				res.setResponse("Updated Successfully ");

			}

			dozerMapper.map(req, saveData);
			saveData.setCityId(Integer.valueOf(cityId));
			saveData.setCityName(req.getCityName());
			saveData.setEffectiveDateStart(effDate);
			saveData.setEffectiveDateEnd(endDate);
			saveData.setStatus(req.getStatus());
			saveData.setEntryDate(new Date());
			repo.saveAndFlush(saveData);

			if (list.size() > 0) {
				// Update Old Record
				CityMaster lastRecord = list.get(0);
				lastRecord.setEffectiveDateEnd(oldEndDate);
				repo.saveAndFlush(lastRecord);
			}

			log.info("Saved Details is ---> " + json.toJson(saveData));

		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			return null;
		}
		return res;
	}

	@Override
	public List<Error> validateCityDetails(CityMasterSaveReq req) {

		List<Error> errorList = new ArrayList<Error>();

		try {

			if (StringUtils.isBlank(req.getCityName()) || req.getCityName() == null) {
				errorList.add(new Error("02", "CityName", "Please Select City  Name "));
			} else if (req.getCityName().length() > 100) {
				errorList.add(new Error("02", "CityName", "Please Enter City  Name within 100 Characters"));
			} else if (StringUtils.isBlank(req.getCityId().toString())) {
				Long CityCount = repo.countByCityNameOrderByEntryDateDesc(req.getCityName());
				if (CityCount > 0) {
					errorList.add(new Error("01", "CityName", "This City Name Alrady Exist "));
				}
			}

			if (StringUtils.isBlank(req.getCountryId()) || req.getCountryId() == null) {
				errorList.add(new Error("03", "CountryId", "Please Select Country Id "));
			} 

			// Date Validation
			Calendar cal = new GregorianCalendar();
			Date today = new Date();
			cal.setTime(today);
			cal.add(Calendar.DAY_OF_MONTH, -1);cal.set(Calendar.HOUR_OF_DAY, 23);cal.set(Calendar.MINUTE, 50);
			today = cal.getTime();
			if (req.getEffectiveDate() == null || StringUtils.isBlank(req.getEffectiveDate().toString())) {
				errorList.add(new Error("04", "EffectiveDateStart", "Please Enter Effective Date Start"));

			} else if (req.getEffectiveDate().before(today)) {
				errorList
						.add(new Error("04", "EffectiveDateStart", "Please Enter Effective Date Start as Future Date"));
			}
			// Status Validation
			if (StringUtils.isBlank(req.getStatus())) {
				errorList.add(new Error("05", "Status", "Please Enter Status"));
			} else if (req.getStatus().length() > 1) {
				errorList.add(new Error("05", "Status", "Status 1 Character Only"));
			} else if (!("Y".equals(req.getStatus()) || "N".equals(req.getStatus()))) {
				errorList.add(new Error("05", "Status", "Enter Status Y or N Only"));
			}

			if (StringUtils.isBlank(req.getStateId()) || req.getStateId() == null) {
				errorList.add(new Error("06", "StateId", "Please Select State Id "));
			} 

		} catch (Exception e) {
			log.error(e);
			e.printStackTrace();
		}
		return errorList;
	}

	public Long getMasterTableCount() {

		Long data = 0L;
		try {

			List<Long> list = new ArrayList<Long>();
			// Find Latest Record
			CriteriaBuilder cb = em.getCriteriaBuilder();
			CriteriaQuery<Long> query = cb.createQuery(Long.class);

			// Find All
			Root<CityMaster> b = query.from(CityMaster.class);

			// Select
			query.multiselect(cb.count(b));

			// Effective Date Max Filter
			Subquery<Long> effectiveDate = query.subquery(Long.class);
			Root<CityMaster> ocpm1 = effectiveDate.from(CityMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(ocpm1.get("cityId"), b.get("cityId"));
			effectiveDate.where(a1);

			Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);
			query.where(n1);
			// Get Result
			TypedQuery<Long> result = em.createQuery(query);
			list = result.getResultList();

			data = list.get(0);

		} catch (Exception e) {
			e.printStackTrace();
			log.info(e.getMessage());

		}
		return data;
	}

///*********************************************************************GET ALL******************************************************\\
	@Override
	public List<CityMasterRes> getallCityDetails(CityMasterGetAllReq req) {
		List<CityMasterRes> resList = new ArrayList<CityMasterRes>();
		ModelMapper mapper = new ModelMapper();
		try {
			List<CityMaster> list = new ArrayList<CityMaster>();
			// Pagination
			int limit = StringUtils.isBlank(req.getLimit()) ? 0 : Integer.valueOf(req.getLimit());
			int offset = StringUtils.isBlank(req.getOffset()) ? 0 : Integer.valueOf(req.getOffset());

			// Find Latest Record
			CriteriaBuilder cb = em.getCriteriaBuilder();
			CriteriaQuery<CityMaster> query = cb.createQuery(CityMaster.class);

			// Find All
			Root<CityMaster> b = query.from(CityMaster.class);

			// Select
			query.select(b);

			// Effective Date Max Filter
			Subquery<Long> effectiveDate = query.subquery(Long.class);
			Root<CityMaster> ocpm1 = effectiveDate.from(CityMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(ocpm1.get("cityId"), b.get("cityId"));
			effectiveDate.where(a1);

			// Order By
			List<Order> orderList = new ArrayList<Order>();
			orderList.add(cb.asc(b.get("cityName")));

			// Where
			Predicate n1 = cb.equal(b.get("effectiveDateStart"), effectiveDate);

			query.where(n1).orderBy(orderList);

			// Get Result
			TypedQuery<CityMaster> result = em.createQuery(query);
			result.setFirstResult(limit * offset);
			result.setMaxResults(offset);
			list = result.getResultList();

			// Map
			for (CityMaster data : list) {
				CityMasterRes res = new CityMasterRes();

				res = mapper.map(data, CityMasterRes.class);
				mapper.getConfiguration().setAmbiguityIgnored(true);
				res.setCityId(data.getCityId().toString());
				resList.add(res);
			}

		} catch (Exception e) {
			e.printStackTrace();
			log.info(e.getMessage());
			return null;

		}
		return resList;
	}

